// B1 #269: salida de error de las escrituras a Odoo del resolver. Ninguna falla queda muda.
// Si falla aquí, el PUT a GitHub no corre: la incidencia NO cambia de estado.
const e = $input.first().json || {};
const err = e.error;
const msg = String((err && typeof err === 'object' ? (err.message || err.description) : err) || e.message || 'sin detalle');
const sinRespuesta = /ECONNRESET|ETIMEDOUT|ECONNREFUSED|ENOTFOUND|EAI_AGAIN|socket hang up|timeout|timed out|429|502|503|504/i.test(msg);
let p = {};
try { p = $('Code - Aplicar accion').first().json || {}; } catch (x) { p = {}; }
return [{ json: {
  success: false,
  codigo: sinRespuesta ? 'ODOO_NO_RESPONDE' : 'ODOO_RECHAZO',
  mensaje: (sinRespuesta ? 'Odoo no respondió.' : 'Odoo rechazó el cambio: ' + msg.slice(0, 300)) +
    ' La incidencia NO cambió de estado; vuelve a intentar.',
  id_interno: p.id_interno || null
} }];

// B1 #269: Odoo ya quedó actualizado, pero el archivo de incidencias no se pudo escribir
// (conflicto de sha u otro error de GitHub). Se avisa en vez de responder éxito.
const e = $input.first().json || {};
const err = e.error;
const msg = String((err && typeof err === 'object' ? (err.message || err.description) : err) || e.message || 'sin detalle');
let p = {};
try { p = $('Code - Preparar PUT').first().json || {}; } catch (x) { p = {}; }
return [{ json: {
  success: false,
  codigo: 'GITHUB_CONFLICTO',
  mensaje: 'Odoo se actualizó, pero el estado de la incidencia no se guardó. Recarga el panel y vuelve a aplicar la acción.',
  detalle_tecnico: msg.slice(0, 300),
  id_interno: p.id_interno || null,
  odoo_aplicado: p.odoo_aplicado === true
} }];
